"use client";
import { useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { api, newKey } from "./api";
import { SlotPicker, type PickedSlot } from "./SlotPicker";
import { Button, Card, Field, inputClass, Notice } from "./ui";

export function ManualBooking({ businessId, slug, today, services }: { businessId: string; slug: string; today: string; services: { id: string; name: string }[] }) {
  const router = useRouter();
  const [date, setDate] = useState(today);
  const [party, setParty] = useState(2);
  const [service, setService] = useState(services[0]?.id ?? "");
  const [slot, setSlot] = useState<PickedSlot | null>(null);
  const [who, setWho] = useState({ name: "", phone: "", email: "", notes: "", tentative: false });
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const key = useRef(newKey());

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    if (!slot) return setError("Choose a time.");
    if (!who.phone.trim() && !who.email.trim()) return setError("Enter a phone number or an email address.");
    setBusy(true); setError("");
    try {
      const r = await api<{ reservation: { id: string } }>(`/api/b/${businessId}/reservations`, {
        body: { serviceId: service || null, startsAt: slot.start, partySize: party, notes: who.notes, tentative: who.tentative, idempotencyKey: key.current,
                customer: { name: who.name, phone: who.phone || null, email: who.email || null } },
      });
      router.push(`/app/${slug}/reservations/${r.reservation.id}`);
    } catch (err) { setError((err as Error).message); setBusy(false); setSlot(null); key.current = newKey(); }
  }

  return (
    <Card className="p-5">
      <form onSubmit={submit} className="space-y-4">
        <div className="grid grid-cols-2 gap-3">
          <Field label="Party size"><input type="number" min={1} max={500} required className={inputClass} value={party} onChange={(e) => { setParty(Math.max(1, Number(e.target.value) || 1)); setSlot(null); }} /></Field>
          <Field label="Date"><input type="date" required min={today} className={inputClass} value={date} onChange={(e) => { setDate(e.target.value); setSlot(null); }} /></Field>
        </div>
        {services.length > 1 && <Field label="Service"><select className={inputClass} value={service} onChange={(e) => { setService(e.target.value); setSlot(null); }}>{services.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select></Field>}
        <div>
          <p className="mb-1.5 text-sm font-semibold text-ink-soft">Time</p>
          <SlotPicker endpoint={`/api/b/${businessId}/availability${service ? `?service=${service}` : ""}`} date={date} party={party} selected={slot?.start ?? null} onPick={setSlot} />
        </div>
        <Field label="Customer name"><input required minLength={2} maxLength={80} className={inputClass} value={who.name} onChange={(e) => setWho({ ...who, name: e.target.value })} /></Field>
        <div className="grid gap-3 sm:grid-cols-2">
          <Field label="Phone"><input type="tel" maxLength={30} className={inputClass} value={who.phone} onChange={(e) => setWho({ ...who, phone: e.target.value })} /></Field>
          <Field label="Email"><input type="email" maxLength={160} className={inputClass} value={who.email} onChange={(e) => setWho({ ...who, email: e.target.value })} /></Field>
        </div>
        <Field label="Note (optional)"><input maxLength={500} className={inputClass} value={who.notes} onChange={(e) => setWho({ ...who, notes: e.target.value })} /></Field>
        <label className="flex items-start gap-2.5 text-[15px] text-ink-soft">
          <input type="checkbox" className="mt-0.5 size-5 accent-[var(--color-brand)]" checked={who.tentative} onChange={(e) => setWho({ ...who, tentative: e.target.checked })} />
          Hold as tentative. The table is kept, but the booking must be confirmed before check-in.
        </label>
        {error && <Notice tone="error">{error}</Notice>}
        <Button type="submit" disabled={busy} className="w-full">{busy ? "Saving…" : "Save reservation"}</Button>
      </form>
    </Card>
  );
}
